-- Sint Maarten 2026 monthly wage-tax withholding (loonbelasting maandtabel).
--
-- Source: AB 2026, no. 11, Bijlage II, maandtabel. The basiskorting is already
-- in the published tax amounts. Rows are wage classes from Cg 1,587.33 through
-- Cg 14,162.33 in steps of Cg 5.00 (2,516 classes).
--
-- Withholding rules, also from that bijlage, live on wage_tax_withholding_rules:
-- - grondslag at or below Cg 2,273.44: withhold nothing
-- - grondslag above the last class: last class tax plus the stored excess rate
--   on the excess (the bijlage states 47.5 percent)
-- - the worked example deducts monthly verwervingskosten of Cg 41.67 before
--   the employee AOV/AWW premium when it builds column 13
--
-- This is the withholding table. It does not replace the annual schijventarief
-- stored on the WAGE_TAX schedule. Python must read these rows.

DELETE FROM allyanna.tax_schedules
WHERE country_code = 'SXM' AND tax_year = 2026 AND schedule_code = 'WAGE_TAX_MONTHLY';

  id, country_code, tax_year, schedule_code, calculation_method, amount_period,
  currency_code, lower_inclusive, upper_inclusive, effective_from, effective_to, source_note
) VALUES (
  'a1000000-0000-4000-8000-000000000004',
  'SXM', 2026, 'WAGE_TAX_MONTHLY', 'wage_class_lookup', 'month', 'XCG',
  true, true, DATE '2026-01-01', DATE '2026-12-31',
  'AB 2026, no. 11 Bijlage II maandtabel, including basiskorting. Apply the wage class at or below the loonbelasting grondslag. At or below the withholding-free maximum, withhold nothing. Above the last class, add the stored excess rate times the excess over that class. Monthly acquisition cost is the verwervingskosten amount from the bijlage worked example.'
);

  tax_schedule_id, withholding_free_maximum, excess_rate, monthly_acquisition_cost
) VALUES (
  'a1000000-0000-4000-8000-000000000004', 2273.44, 0.47500000, 41.67
);


UPDATE allyanna.szv_components AS component
SET reduces_wage_tax_base = component.component_code IN ('AOV', 'AWW')
FROM allyanna.tax_schedules AS schedule
WHERE component.tax_schedule_id = schedule.id
  AND schedule.country_code = 'SXM'
  AND schedule.tax_year = 2026
  AND schedule.schedule_code = 'SZV';

